  PROCESSING "LOAD_WHOLE_IMAGE=YES"
  PROCESSING "RESAMPLE=BILINEAR"
  
  METADATA
    "wms_title"          "Mass content of zooplankton expressed as carbon in sea water"
    "wms_abstract"       "This map shows the biomass of zooplankton across the global ocean, expressed in terms of carbon content. Zooplankton are small marine animals that drift or swim with ocean currents, including tiny crustaceans and other organisms that feed on phytoplankton or smaller animals. They play an essential role in marine food webs by transferring energy from microscopic producers to fish and other larger marine species. Using daily Copernicus Marine data, the map helps users explore where zooplankton biomass is concentrated, how it varies over time and what these patterns may reveal about the productivity of marine ecosystems."
    "wms_name"           "GLOBAL_MULTIYEAR_BGC_001_033/cmems_mod_glo_bgc_my_0.083deg-lmtl_P1D-i_202511/zooc"
    "wms_format"         "image/png"
    "wms_server_version"  "1.3.0"
    "wms_timeextent"     "1998-01-01/2025-06-30/P1D"
    "wms_timeitem"       "TIME"
    "wms_srs"                 "EPSG:3857"
    "wms_extent"              "-20037508.34 -20037508.34 20037508.34 20037508.34"
    "wms_connection_request_metadata" "LAYER STYLE GROUP"
    "wms_layer"          "zooc"
    "wms_style"          "cmap:matter"
    "wms_layer_group"           "/GLOBAL_MULTIYEAR_BGC_001_033/cmems_mod_glo_bgc_my_0.083deg-lmtl_P1D-i_202511"
    "wms_group_title"           "Global ocean low and mid trophic levels biomass content hindcast"
    "wms_group_abstract" "This collection of Copernicus Marine maps shows daily estimates of marine biomass and environmental conditions across the global ocean. The layers include zooplankton biomass, six groups of micronekton (small swimming animals such as fish, squid and crustaceans), net primary productivity (the rate at which marine plants produce organic matter) and euphotic zone depth (the depth to which sufficient sunlight penetrates for photosynthesis). The maps combine modelled estimates of past ocean conditions with supporting environmental data. Together, they help users explore how marine food webs and the conditions that support them vary across regions and over time."
  END
  
